async function seed() {
  console.log('Seeding estantes...')
  const { error: e1 } = await db.from('estantes').upsert(ESTANTES, { onConflict: 'key' })
  if (e1) { console.error('Erro estantes:', e1); process.exit(1) }
  console.log(`  ✓ ${ESTANTES.length} estantes`)

  console.log('Seeding materiais...')
  const { error: e2 } = await db.from('materiais').upsert(MATERIAIS, { onConflict: 'id' })
  if (e2) { console.error('Erro materiais:', e2); process.exit(1) }
  console.log(`  ✓ ${MATERIAIS.length} materiais`)

  console.log('Seeding cursos...')
  const { error: e3 } = await db.from('cursos').upsert(CURSOS, { onConflict: 'slug' })
  if (e3) { console.error('Erro cursos:', e3); process.exit(1) }
  console.log(`  ✓ ${CURSOS.length} cursos`)

  console.log('\n✅ Seed concluído!')
}

seed()
